import { configureOrtWeb, loadHuggingfaceModel } from 'onnx-asr-web/browser';

// BlackRiver Voice 1.4.2
// ----------------------
// Use the exact Parakeet stack already proven in BlackRiver OmniVoice:
//   onnx-asr-web 0.1.3
//   Olicorne/parakeet-tdt-0.6b-v3-smoothquant-onnx
//   INT8 + WASM execution
//
// ASR deliberately stays off WebGPU. The main QwiVer Wllama runtime keeps the
// GPU, while Parakeet transcribes on the CPU/WASM sidecar. Natural / Prompt
// shaping still happens afterwards in the independent Qwen3.5-0.8B Wllama
// sidecar.
const PARAKEET_REPO = 'Olicorne/parakeet-tdt-0.6b-v3-smoothquant-onnx';
const PARAKEET_REVISION = 'main';
const PARAKEET_LABEL = 'Parakeet TDT 0.6B v3';
const ASR_ORT_CDN = 'https://cdn.jsdelivr.net/npm/onnxruntime-web@1.27.0/dist/';

configureOrtWeb({
  wasmPaths: ASR_ORT_CDN,
  numThreads: globalThis.crossOriginIsolated
    ? Math.max(1, Math.min(8, globalThis.navigator?.hardwareConcurrency || 4))
    : 1,
  simd: true,
  proxy: false,
});

let model = null;
let loadPromise = null;

function safePost(message) {
  self.postMessage(message);
}

function cleanTranscript(text = '') {
  return String(text || '')
    .replace(/\s+/g, ' ')
    .replace(/\s+([,.;!?])/g, '$1')
    .trim();
}

async function ensureModel(requestId) {
  if (model) return model;
  if (loadPromise) return loadPromise;

  loadPromise = (async () => {
    safePost({
      type: 'phase',
      requestId,
      phase: 'loading-asr',
      label: 'Loading Parakeet TDT',
    });
    // onnx-asr-web lets ORT fetch the ONNX graph URLs directly, so there is no
    // reliable byte callback here. Keep the UI indeterminate rather than fake a
    // percentage.
    safePost({
      type: 'progress',
      requestId,
      stage: 'parakeet',
      label: PARAKEET_LABEL,
      event: { file: 'Parakeet multilingual INT8', loaded: 0, total: 0, progress: null },
    });

    const instance = await loadHuggingfaceModel(PARAKEET_REPO, {
      revision: PARAKEET_REVISION,
      quantization: 'int8',
      sessionOptions: {
        executionProviders: ['wasm'],
        graphOptimizationLevel: 'all',
        enableCpuMemArena: true,
      },
      decoderOptions: { maxSymbols: 10 },
    });

    model = instance;
    safePost({ type: 'phase', requestId, phase: 'asr-ready', label: 'Parakeet ready' });
    return instance;
  })();

  try {
    return await loadPromise;
  } catch (error) {
    model = null;
    throw error;
  } finally {
    loadPromise = null;
  }
}

async function runTranscription(requestId, audioBuffer, sampleRate, settings = {}) {
  const instance = await ensureModel(requestId);
  const audio = new Float32Array(audioBuffer);
  const rate = Number(sampleRate) || 16_000;

  safePost({ type: 'phase', requestId, phase: 'transcribing', label: 'Transcribing with Parakeet' });

  // This is the exact high-level API used by BlackRiver OmniVoice. It accepts
  // normalized mono Float32 PCM and handles resampling internally when needed.
  const result = await instance.transcribeSamples(audio, rate);
  const raw = cleanTranscript(result?.text || '');

  console.info('[BlackRiver Voice] Parakeet transcript', {
    repository: PARAKEET_REPO,
    sampleRate: rate,
    samples: audio.length,
    duration: audio.length / rate,
    transcript: raw,
    words: result?.words?.length || 0,
  });

  safePost({ type: 'raw', requestId, raw, asr: 'parakeet-tdt-0.6b-v3-smoothquant' });
  safePost({
    type: 'result',
    requestId,
    raw,
    cleaned: raw,
    mode: settings.mode === 'raw' ? 'raw' : settings.mode === 'prompt' ? 'prompt' : 'natural',
    asr: 'parakeet-tdt-0.6b-v3-smoothquant',
    needsRefine: settings.mode !== 'raw',
    words: result?.words || [],
  });
}

self.onmessage = async ({ data }) => {
  const requestId = data?.requestId;
  try {
    if (data?.type === 'load') {
      await ensureModel(requestId);
      safePost({ type: 'ready', requestId });
      return;
    }
    if (data?.type === 'transcribe') {
      await runTranscription(requestId, data.audio, data.sampleRate, data.settings || {});
    }
  } catch (error) {
    console.error('[BlackRiver Voice] Parakeet worker failed', error);
    safePost({
      type: 'error',
      requestId,
      message: error?.message || String(error) || 'BlackRiver Voice failed.',
      name: error?.name || 'Error',
    });
  }
};
